\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── Ocean-to-warming color theme ──
% Deep ocean blues → warning reds/ambers
\definecolor{primary}{HTML}{0A2E5C}     % deep ocean navy
\definecolor{secondary}{HTML}{1565A8}   % mid ocean blue
\definecolor{accent}{HTML}{C0392B}      % warming red
\definecolor{amber}{HTML}{D4700A}       % amber warm
\definecolor{teal}{HTML}{117A8B}        % teal accent
\definecolor{bgposter}{HTML}{EAF2F8}    % cool pale blue-white bg
\definecolor{redbg}{HTML}{FEF0ED}       % warm card bg
\definecolor{bluebg}{HTML}{EBF5FB}      % cool card bg
\definecolor{darkbg}{HTML}{E8EFF7}      % navy card bg
\definecolor{tealcard}{HTML}{E8F5F7}    % teal card bg
\definecolor{redtitlebg}{HTML}{FADBD8}
\definecolor{bluetitlebg}{HTML}{D6EAF8}
\definecolor{darktitlebg}{HTML}{D1E0F0}
\definecolor{tealtitlebg}{HTML}{D0ECF0}
\definecolor{textdark}{HTML}{0D1B2E}
\definecolor{textgray}{HTML}{2C4A6E}
\definecolor{statbg}{HTML}{FEF9E7}
\definecolor{statred}{HTML}{FDEDEC}
\definecolor{warnred}{HTML}{E74C3C}
\definecolor{goldaccent}{HTML}{F39C12}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Sub-header command ──
\newcommand{\subheader}[1]{%
  {\fontsize{32}{40}\selectfont\bfseries\color{primary} #1}\par\vspace{3pt}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealcard,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={teal!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!16!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════════
%  TITLE BAR  (rows 1–4, all 3 columns)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  interior style={
    left color=primary,
    right color=secondary!60!primary
  },
  drop shadow={opacity=0.35}
]{name=titlebox, column=1, span=3, between=top and row4}{%
  {\fontsize{74}{88}\selectfont\bfseries\color{white}
    300 Years of Sclerosponge Thermometry}\\[6pt]
  {\fontsize{52}{64}\selectfont\bfseries\color{white!90}
    Shows Global Warming Has Exceeded 1.5\,\textdegree{}C}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{white!80}
    Caribbean Sr/Ca Proxy Records (1700–2020)
    $\;\cdot\;$ \textit{Nature Climate Change}, 2024}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{white!65}
    AGU\,/\,Nature Climate Change Symposium
    $\;\cdot\;$
    Proxy Thermometry\,\textbullet\,Pre-Industrial Baselines\,\textbullet\,Paris Agreement}%
}

% ═══════════════════════════════════════════════════════════════
%  STATS BANNER  (rows 4–6, all 3 columns)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=8pt, bottom=8pt,
  valign=center,
  borderline north={2pt}{0pt}{primary!30},
  borderline south={3pt}{0pt}{accent!60},
]{name=statsbox, column=1, span=3, between=row4 and row6}{%
  \centering
  % Stat 1
  \begin{minipage}[c]{0.230\linewidth}\centering
    \fcolorbox{accent!50}{statred}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{accent} {>}1.5\,\textdegree{}C}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Total warming (true baseline)}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 2
  \begin{minipage}[c]{0.230\linewidth}\centering
    \fcolorbox{amber!50}{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{amber} +0.5\,\textdegree{}C}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Hidden warming missed by IPCC}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 3
  \begin{minipage}[c]{0.230\linewidth}\centering
    \fcolorbox{secondary!40}{bluebg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{secondary} 300 yrs}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Proxy record (back to 1700\,CE)}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 4
  \begin{minipage}[c]{0.230\linewidth}\centering
    \fcolorbox{teal!40}{tealcard}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{teal} r$^2${>}0.9}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Sr/Ca calibration vs.\ instrumental}\vspace{5pt}%
    }}
  \end{minipage}%
}

% ═══════════════════════════════════════════════════════════════
%  COLUMN 1  ─  rows 6–20
% ═══════════════════════════════════════════════════════════════

% ── Background & Why Sclerosponges? (rows 6–11) ──
\posterbox[darkcard, title={Why Sclerosponges?}
]{name=background, column=1, between=row6 and row11}{%
  \fontsize{30}{40}\selectfont%
  Long-lived marine organisms; Ca\-ribbean reefs; depths 33–91\,m.
  Their aragonite skeletons encode \textbf{annual Sr/Ca ratios}
  that faithfully track sea-surface temperature.
  \vspace{6pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{Key advantage:} Continuous record extends to $\sim$1700\,CE ---
    well before any thermometer network existed.}}
  \vspace{6pt}

  \begin{itemize}
    \item Unbroken, \textbf{annual-resolution} record over 3 centuries
    \item Tropical sensitivity: captures large-scale SST variability
    \item Completely \textbf{independent} of instrumental datasets
    \item Calibrated against HadCRUT5 / NOAA ERSSTv5 (1960--present)
  \end{itemize}
  \vspace{4pt}

  \colorbox{teal!20}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont
    $\Rightarrow$ \textbf{Sr/Ca calibration:} $r^{2} > 0.90$ vs.\ co-located
    instrumental SST records 1960--2020.}}
}

% ── Key Finding: Baseline Matters (rows 11–16) ──
\posterbox[redcard, title={The Hidden 0.5\,\textdegree{}C}
]{name=keyfinding, column=1, between=row11 and row16}{%
  \fontsize{30}{40}\selectfont%
  The IPCC uses 1850--1900 as ``pre-industrial''---but that era already
  contained significant anthropogenic warming.

  \vspace{8pt}
  \begin{center}
  \renewcommand{\arraystretch}{1.7}
  \fontsize{27}{34}\selectfont
  \begin{tabular}{lcc}
    \rowcolor{primary!15}
    \textbf{Baseline} & \textbf{Warming to 2020} & \textbf{Source}\\
    1850--1900 (IPCC) & $\sim$1.2\,\textdegree{}C & HadCRUT5 / AR6\\
    \rowcolor{accent!12}
    \textbf{1700--1790 (true)} & \textbf{{>}1.5\,\textdegree{}C} & \textbf{Sclerosponge}\\
    \hline
    Difference & \textcolor{accent}{\textbf{+0.5\,\textdegree{}C}} & This study\\
  \end{tabular}
  \end{center}
  \vspace{6pt}

  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{Key:} Half a degree of warming occurred \emph{before} the
    conventional baseline begins---the 1.5\,\textdegree{}C threshold
    was crossed in the early 2020s.}}
}

% ── Methods (rows 16–20) ──
\posterbox[tealcard, title={Data \& Methods}
]{name=methods, column=1, between=row16 and bottom}{%
  \fontsize{29}{38}\selectfont%
  \begin{itemize}
    \item Caribbean sites; depths \textbf{33--91\,m}
    \item Sr/Ca measured by \textbf{ICP-OES}
    \item Calibrated vs.\ co-located SST 1960--2020
    \item Validated: HadCRUT5, NOAA ERSSTv5
    \item Divergence only pre-1850---precisely where hidden warming resides
  \end{itemize}
  \vspace{4pt}
  \colorbox{teal!18}{\parbox{0.94\linewidth}{%
    \fontsize{28}{35}\selectfont
    Specimens collected from continuous-growth colonies;
    no gaps in skeletal record over 300 years.}}
}

% ═══════════════════════════════════════════════════════════════
%  COLUMN 2  ─  Temperature Reconstruction (hero figure, rows 6–20)
% ═══════════════════════════════════════════════════════════════
\posterbox[bluecard, title={300-Year Temperature Reconstruction}
]{name=mainchart, column=2, between=row6 and bottom}{%
  \vspace{2pt}
  \posterfig{0.98}{figures/temp_reconstruction.png}{%
    \textbf{Fig.\ 1.}\ Caribbean sclerosponge Sr/Ca temperature anomaly (cyan)
    relative to the true pre-industrial baseline (1700--1790),
    vs.\ the instrumental record referenced to the IPCC 1850--1900 baseline
    (dashed orange). The red horizontal line marks the Paris Agreement
    1.5\,\textdegree{}C threshold; the gold bracket shows the 0.5\,\textdegree{}C
    gap between records. Triangles indicate major volcanic eruptions.
    Shading shows proxy uncertainty ($\pm 1\sigma$).}
  \vspace{4pt}

  \colorbox{accent!18}{\parbox{0.96\linewidth}{%
    \centering\fontsize{31}{40}\selectfont\bfseries\color{accent}
    The proxy curve \emph{crosses 1.5\,\textdegree{}C} in the early 2020s.
    The instrumental record, anchored to the later baseline, shows only
    $\sim$1.2\,\textdegree{}C---a systematic underestimate.}}
  \vspace{6pt}

  \subheader{Timeline of Key Milestones}
  \fontsize{28}{38}\selectfont%
  \renewcommand{\arraystretch}{1.65}
  \begin{tabular}{ll}
    \rowcolor{primary!12}
    \textbf{Period} & \textbf{Observation}\\
    1700--1790 & Stable pre-industrial; \textbf{true zero}\\
    1790--1850 & Onset of detectable warming\\
    \rowcolor{amber!15}
    1850--1900 & \textbf{Already +0.5\,\textdegree{}C} above true baseline\\
    1900--1960 & Gradual rise; volcanic dips visible\\
    1960--2000 & Accelerating; proxy $\approx$ instrumental\\
    \rowcolor{accent!18}
    2000--present & \textbf{{>}1.5\,\textdegree{}C} --- threshold exceeded\\
  \end{tabular}
}

% ═══════════════════════════════════════════════════════════════
%  COLUMN 3  ─  rows 6–20
% ═══════════════════════════════════════════════════════════════

% ── Policy Implications (rows 6–12) ──
\posterbox[redcard, title={Policy \& Climate Target Implications}
]{name=implications, column=3, between=row6 and row13}{%
  \fontsize{30}{40}\selectfont%

  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{31}{40}\selectfont\bfseries
    The Paris Agreement's 1.5\,\textdegree{}C target is already
    surpassed when measured against a \emph{true} pre-industrial baseline.}}
  \vspace{8pt}

  \begin{itemize}
    \item Remaining \textbf{carbon budget for 1.5\,\textdegree{}C: effectively zero}
    \item 2.0\,\textdegree{}C guardrail: only $\sim$0.3\,\textdegree{}C remaining
          (not $\sim$0.8\,\textdegree{}C as previously estimated)
    \item Conventional instrumental records \textbf{mask urgency}
          by anchoring to an already-warm baseline
    \item Baseline transparency must become part of IPCC reporting
  \end{itemize}
  \vspace{6pt}

  \colorbox{amber!22}{\parbox{0.94\linewidth}{%
    \fontsize{29}{37}\selectfont
    $\Rightarrow$ \textbf{Revised 2\,\textdegree{}C budget:}
    $\sim$0.3\,\textdegree{}C vs.\ previously reported $\sim$0.8\,\textdegree{}C---
    a \textbf{62\,\% reduction} in remaining headroom.}}
  \vspace{6pt}

  \begin{itemize}
    \item Findings underscore \textbf{immediate emissions reductions}
    \item Proxy-augmented baselines needed for policy targets
  \end{itemize}
}

% ── Key Findings / Contributions (rows 13–17) ──
\posterbox[highlightcard, title={Key Findings}
]{name=findings, column=3, between=row13 and row17}{%
  \fontsize{30}{40}\selectfont%
  \begin{enumerate}
    \item \textbf{1700--1790 baseline} reveals $>$1.5\,\textdegree{}C total warming,
          not the $\sim$1.2\,\textdegree{}C in standard reports
    \item IPCC's 1850--1900 reference is \textbf{not} pre-industrial;
          it already contains $\sim$0.5\,\textdegree{}C of anthropogenic signal
    \item Sclerosponge Sr/Ca provides \textbf{continuous, annually-resolved}
          SST back to 1700---no gaps, no splicing
    \item Proxy and instrumental records \textbf{agree excellently} from
          1960 onward ($r^{2} > 0.90$)
  \end{enumerate}
}

% ── Takeaways (rows 17–20) ──
\posterbox[darkcard, title={Takeaways}
]{name=takeaways, column=3, between=row17 and bottom}{%
  \fontsize{30}{40}\selectfont%
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \fontsize{31}{40}\selectfont
    \textbf{The 1.5\,\textdegree{}C Paris threshold has been crossed.}
    The remaining climate question is not \emph{whether} to avoid it,
    but \emph{how quickly} we limit further overshoot.}}
  \vspace{8pt}

  \begin{itemize}
    \item Proxy thermometry \textbf{must inform} international baselines
    \item Sclerosponges: gold-standard for pre-1850 tropical SST
    \item Future work: \textbf{Indo-Pacific} and Southern Ocean sponge networks
  \end{itemize}
  \vspace{6pt}

  {\fontsize{27}{34}\selectfont\color{textgray}
    \textit{Nature Climate Change} (2024)
    $\cdot$ DOI: 10.1038/s41558-024-XXXX-X
    $\cdot$ Data: NOAA Paleoclimate Archive}
}

\end{tcbposter}
\end{document}

