    \item Sclerosponge Sr/Ca provides \textbf{continuous, annually-resolved}
          SST back to 1700---no gaps, no splicing
    \item Proxy and instrumental records \textbf{agree excellently} from
          1960 onward ($r^{2} > 0.90$)
  \end{enumerate}
}

