\definecolor{primary}{HTML}{0A2E5C}     % deep ocean navy
\definecolor{secondary}{HTML}{1565A8}   % mid ocean blue
\definecolor{accent}{HTML}{C0392B}      % warming red
\definecolor{amber}{HTML}{D4700A}       % amber warm
\definecolor{teal}{HTML}{117A8B}        % teal accent
\definecolor{bgposter}{HTML}{EAF2F8}    % cool pale blue-white bg
\definecolor{redbg}{HTML}{FEF0ED}       % warm card bg
\definecolor{bluebg}{HTML}{EBF5FB}      % cool card bg
\definecolor{darkbg}{HTML}{E8EFF7}      % navy card bg
\definecolor{tealcard}{HTML}{E8F5F7}    % teal card bg
\definecolor{redtitlebg}{HTML}{FADBD8}
\definecolor{bluetitlebg}{HTML}{D6EAF8}
\definecolor{darktitlebg}{HTML}{D1E0F0}
\definecolor{tealtitlebg}{HTML}{D0ECF0}
\definecolor{textdark}{HTML}{0D1B2E}
\definecolor{textgray}{HTML}{2C4A6E}
\definecolor{statbg}{HTML}{FEF9E7}
\definecolor{statred}{HTML}{FDEDEC}
\definecolor{warnred}{HTML}{E74C3C}
\definecolor{goldaccent}{HTML}{F39C12}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Sub-header command ──
\newcommand{\subheader}[1]{%
  {\fontsize{32}{40}\selectfont\bfseries\color{primary} #1}\par\vspace{3pt}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
