    \rowcolor{accent!12}
    \textbf{1700--1790 (true)} & \textbf{{>}1.5\,\textdegree{}C} & \textbf{Sclerosponge}\\
    \hline
    Difference & \textcolor{accent}{\textbf{+0.5\,\textdegree{}C}} & This study\\
  \end{tabular}
  \end{center}
  \vspace{6pt}

  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{Key:} Half a degree of warming occurred \emph{before} the
    conventional baseline begins---the 1.5\,\textdegree{}C threshold
    was crossed in the early 2020s.}}
}

% ── Methods (rows 16–20) ──
\posterbox[tealcard, title={Data \& Methods}
]{name=methods, column=1, between=row16 and bottom}{%
  \fontsize{29}{38}\selectfont%
  \begin{itemize}
    \item Caribbean sites; depths \textbf{33--91\,m}
    \item Sr/Ca measured by \textbf{ICP-OES}
    \item Calibrated vs.\ co-located SST 1960--2020
    \item Validated: HadCRUT5, NOAA ERSSTv5
    \item Divergence only pre-1850---precisely where hidden warming resides
  \end{itemize}
  \vspace{4pt}
  \colorbox{teal!18}{\parbox{0.94\linewidth}{%
    \fontsize{28}{35}\selectfont
    Specimens collected from continuous-growth colonies;
    no gaps in skeletal record over 300 years.}}
}

% ═══════════════════════════════════════════════════════════════
%  COLUMN 2  ─  Temperature Reconstruction (hero figure, rows 6–20)
% ═══════════════════════════════════════════════════════════════
\posterbox[bluecard, title={300-Year Temperature Reconstruction}
]{name=mainchart, column=2, between=row6 and bottom}{%
  \vspace{2pt}
  \posterfig{0.98}{figures/temp_reconstruction.png}{%
